/**
 * `pnpm assets:measure`: re-measures every audio row from the file it ships
 * (polish spec §8.1).
 *
 * - Every row gets `peakDbfs`, its sample peak.
 * - Every one-shot (`sfx.*`, `ui.*`, `vo.*`) also gets its `loudnessLufs`
 *   re-measured, because a cue regenerated by `generate-cues.ts` changes level
 *   and that tool writes no rows of its own.
 * - Music and beds keep the loudness their own tools measured: `intake-song.ts`
 *   from the master, `generate-sounds.ts` after `loudnorm`.
 *
 * `tests/asset-contract/audio-loudness-bands.test.ts` then holds each kind to
 * its band. Needs ffmpeg and ffprobe.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { loudnessLufs, peakDb, round2 } from "./audio-measure";

const ASSETS = resolve(import.meta.dirname, "..", "assets");
const MANIFEST = resolve(ASSETS, "art-manifest.json");
const ONE_SHOT = /^(sfx|ui|vo)\./;

type Row = Record<string, unknown> & { readonly role: string; readonly alias: string; readonly file: string };

const manifest = JSON.parse(readFileSync(MANIFEST, "utf8")) as { bundles: Record<string, Row[]> };
let measured = 0;
for (const rows of Object.values(manifest.bundles)) {
  for (const row of rows) {
    if (row.role !== "audio") continue;
    const path = resolve(ASSETS, row.file);
    row["peakDbfs"] = round2(peakDb(path));
    if (ONE_SHOT.test(row.alias)) row["loudnessLufs"] = round2(loudnessLufs(path));
    measured += 1;
  }
}
writeFileSync(MANIFEST, `${JSON.stringify(manifest, null, 2)}\n`);
process.stdout.write(`measured ${measured} audio rows\n`);
